def findBoundaries(points):
    min_x = points[0][0]
    max_x = points[0][0]

    for p in points:
        if p[0] < min_x:
            min_x = p[0]
        if p[0] > max_x:
            max_x = p[0]

    return min_x, max_x

points = []
while True:
    ans = input("Enter point (x,y): ")
    if ans == "0,0":
        break
    p = [float(ans.split(",")[0]), float(ans.split(",")[1])]
    points.append(p)

min_x, max_x = findBoundaries(points)
print("min x", min_x)
print("max x", max_x)

